{
  "answers": [
    {
      "question_id": "Q1",
      "question": "What event or action currently starts the summarization process after a meeting ends — for example, does a specific person manually initiate it, or is it triggered automatically by a system such as a calendar or conferencing tool?",
      "answer": "The process is manually initiated by the minute taker, who begins by collecting meeting notes or the transcript after the meeting concludes. No automatic trigger from a calendar or conferencing system is specified."
    },
    {
      "question_id": "Q2",
      "question": "How is the meeting summary currently created — is it written manually by a participant, derived from a recorded transcript, or generated with the help of an automated or AI-based tool?",
      "answer": "The minute taker manually collects meeting notes or a transcript, then extracts decisions and action items to draft the summary. Automation support for extraction and drafting is identified as an opportunity but is not the current practice."
    },
    {
      "question_id": "Q3",
      "question": "How is the list of email recipients determined — is it always the set of meeting attendees, a predefined distribution list, or does the sender decide case by case?",
      "answer": "The email is sent to 'relevant recipients,' but the exact method for determining that list is not specified in detail. It is not explicitly stated whether it defaults to attendees, a fixed list, or a case-by-case decision."
    },
    {
      "question_id": "Q4",
      "question": "Does the summary need to be reviewed or approved by anyone before the email is sent, and if so, who holds that responsibility?",
      "answer": "No formal review or approval step before sending is specified. However, the minute taker may confirm unclear items with decision owners before drafting, which serves as an informal validation step rather than a structured approval gate."
    },
    {
      "question_id": "Q5",
      "question": "What content is expected to appear in the summary email — for instance, is it a free-form narrative, or must it include structured elements such as action items, owners, and deadlines?",
      "answer": "The summary email is structured and must include decisions made, action items with assigned owners, and deadlines. Supporting materials may also be attached or linked. It is not a free-form narrative."
    },
    {
      "question_id": "Q6",
      "question": "Is there a target or maximum time limit within which the summary email must be sent after the meeting concludes?",
      "answer": "No specific time limit or deadline for sending the summary email after the meeting is mentioned. This detail is not specified in the workflow."
    }
  ]
}
